  function syncTheme() {
    function outside(selector){return Array.prototype.find.call(document.querySelectorAll(selector),function(node){return !root.contains(node);});}
    function background(node){while(node){var color=getComputedStyle(node).backgroundColor;if(color&&color!=='transparent'&&color!=='rgba(0, 0, 0, 0)')return color;node=node.parentElement;}return 'rgb(255, 255, 255)';}
    var surface = outside('.post-content') || outside('#pun-main') || document.body;
    var control = outside('#main-reply,textarea[name="req_message"],textarea[name="message"]') || outside('input[type="text"],textarea,select');
    var link = outside('#pun-main .post-content a,#pun-main h2 a,#pun-navlinks a') || outside('#pun-main a');
    var surfaceStyle = getComputedStyle(surface), bodyStyle = getComputedStyle(document.body);
    var controlStyle = control ? getComputedStyle(control) : surfaceStyle;
    var accent = link ? getComputedStyle(link).color : bodyStyle.color;
    var surfaceBackground=background(surface),controlBackground=control?background(control):surfaceBackground;
    root.style.setProperty('--atb-bg', surfaceBackground);
    root.style.setProperty('--atb-card', surfaceBackground);
    root.style.setProperty('--atb-control', controlBackground);
    root.style.setProperty('--atb-control-text', controlStyle.color || surfaceStyle.color);
    var rgb=controlBackground.match(/[\d.]+/g)||[255,255,255];
    root.style.setProperty('--atb-scheme',Number(rgb[0])*.299+Number(rgb[1])*.587+Number(rgb[2])*.114<128?'dark':'light');
    root.style.setProperty('--atb-text', surfaceStyle.color || bodyStyle.color);
    root.style.setProperty('--atb-accent', accent || surfaceStyle.color);
    root.style.setProperty('--atb-line', controlStyle.borderColor || accent);
  }
  syncTheme();
  var themeFrame=0;
  function scheduleTheme(){if(themeFrame)return;themeFrame=requestAnimationFrame(function(){themeFrame=0;syncTheme();});}
  new MutationObserver(scheduleTheme).observe(document.documentElement, { attributes: true, attributeFilter: ['class', 'style', 'data-theme'] });
  if(document.body)new MutationObserver(scheduleTheme).observe(document.body,{attributes:true,attributeFilter:['class','style','data-theme']});
  new MutationObserver(scheduleTheme).observe(document.head,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['href','media','disabled']});
  document.addEventListener('change',function(event){if(!root.contains(event.target))scheduleTheme();});
  document.addEventListener('load',function(event){if(event.target.tagName==='LINK')scheduleTheme();},true);
  if(document.fonts&&document.fonts.addEventListener)document.fonts.addEventListener('loadingdone',scheduleTheme);

  var tooltip = document.createElement('div');
