  function addRequirement(skill,level){var row=document.createElement('div');row.className='atb-requirement-row';row.innerHTML='<select>'+requirementOptions(skill||'Знания')+'</select><input type="number" min="0" max="20" value="'+esc(level||value('requirement')||1)+'" aria-label="Уровень навыка"><button type="button" class="atb-remove-requirement" aria-label="Удалить">×</button>';root.querySelector('.atb-requirements').appendChild(row);Array.prototype.forEach.call(row.querySelectorAll('select,input'),function(node){node.addEventListener('input',render);node.addEventListener('change',render);});row.querySelector('button').onclick=function(){row.remove();render();};}
