  Array.prototype.forEach.call(root.querySelectorAll('input,select,textarea'),function(n){n.addEventListener('input',function(){if(['damage','protection','healing','activationChakra','generalChakra','maintenance','requirement','effectText'].indexOf(n.name)>=0)dirty[n.name]=true;recalc(false);});n.addEventListener('change',function(){recalc(false);});});
