  function field(title,name,markup,weapon){return '<label class="atb-field'+(weapon?' aab-weapon':'')+'"><span>'+title+'<button class="atb-help" type="button" aria-label="Справка" data-tip="'+esc(help[name]||title)+'">?</button></span>'+ (markup||'<input name="'+name+'">')+'</label>';}
