  app.querySelectorAll('.atb-help').forEach(function(button){function show(){tip.textContent=button.getAttribute('data-tip');tip.hidden=false;var r=button.getBoundingClientRect(),b=tip.getBoundingClientRect();tip.style.left=Math.max(12,Math.min(innerWidth-b.width-12,r.left+r.width/2-b.width/2))+'px';tip.style.top=Math.max(12,Math.min(innerHeight-b.height-12,r.top-b.height-9<12?r.bottom+9:r.top-b.height-9))+'px';}button.addEventListener('mouseenter',show);button.addEventListener('focus',show);button.addEventListener('click',show);button.addEventListener('mouseleave',function(){tip.hidden=true;});button.addEventListener('blur',function(){tip.hidden=true;});});window.addEventListener('scroll',function(){tip.hidden=true;},true);
  var style=document.createElement('style');style.textContent='#atb-root>.atb-launch{margin:0 10px 12px 0}#atb-root .aab-app{margin-top:12px}#atb-root .aab-app .atb-close{color:inherit}#atb-root .aab-upgrade-note{color:var(--atb-accent)}#atb-root .aab-app .atb-grid{align-items:stretch}#atb-root .aab-app .atb-field>span{display:flex;align-items:center;gap:7px;min-height:2.7em;line-height:1.3}#atb-root .aab-app .atb-field>span>.atb-help{flex:0 0 21px;margin:0}#atb-root .aab-app .atb-field>input,#atb-root .aab-app .atb-field>select{margin-top:auto}#atb-root .aab-app .atb-check{align-self:center}@media(max-width:800px){#atb-root .aab-app .atb-field>span{min-height:0}}';document.head.appendChild(style);
  function q(n){return app.querySelector('[name="'+n+'"]');}function v(n){return q(n).value.trim();}function n(k){return Math.max(0,Math.ceil(Number(v(k))||0));}
  function upgradeAllowed(){return !!selected&&Object.keys(colors).indexOf(v('rank'))>Object.keys(colors).indexOf(selected.rank);}
  function increase(text,amount){if(!amount)return text;if(/^\d+(?:[.,]\d+)?/.test(text))return text.replace(/^\d+(?:[.,]\d+)?/,function(x){return Math.ceil(Number(x.replace(',','.'))+amount);});return text?text+' + '+amount:amount+' ед.';}
  function render(){var weapon=v('kind')==='weapon',allowed=upgradeAllowed();Array.prototype.forEach.call(app.querySelectorAll('.aab-weapon'),function(x){x.hidden=!weapon;});q('latinTitle').closest('label').hidden=!q('latin').checked;
    if(weapon)q('base').setAttribute('list','aab-weapons');else q('base').removeAttribute('list');q('base').placeholder=weapon?'Начните вводить название':'Введите базовый тип вручную';
    ['extraDamage','extraCritical','extraChance'].forEach(function(k){q(k).disabled=!allowed;});app.querySelector('.aab-upgrade-note').textContent=allowed?'Можно увеличить характеристики: ранг артефакта выше ранга базового оружия.':'Увеличение характеристик доступно только при ранге артефакта выше ранга базового оружия.';
    var title=v('title')||'Название артефакта',fullTitle=q('latin').checked&&v('latinTitle')?title+' / '+v('latinTitle'):title,color=colors[v('rank')],damage=increase(v('damage'),allowed?n('extraDamage'):0),critical=increase(v('critical'),allowed?n('extraCritical'):0),chance=Math.min(100,n('chance')+(allowed?n('extraChance'):0));
    function line(label,text){return '[b]'+label+': [/b][i]'+(text||'...')+'[/i]';}
    var lines=[line('Ранг артефакта',v('rank')),line('Базовый тип',v('base')||(weapon?'Оружие':'Поддержка'))];if(weapon)lines.push(line('Тип урона',v('damageType')));lines.push(line('Варианты использования',v('usage')),line('Размер',v('size')));if(weapon)lines.push(line('Урон',damage),line('Критический урон',critical+(critical&&critical!=='-'&&critical!=='—'?' (вероятность '+chance+'%)':'')));lines.push(line('Материал',v('material')));
    var notes=[];if(v('requirements'))notes.push('Для использования требуется: '+v('requirements'));notes=notes.concat(v('notes').split(/\n+/).map(function(x){return x.trim();}).filter(Boolean));
    var parameterLink='[url='+(v('postUrl')||'ссылка на пост с артефактом')+'][color='+color+']'+title.replace(/\[\/?widepost\]/gi,'')+'[/color][/url]';var parameterCode='\n[b]Код для вставки в параметры[/b]\n[code]'+parameterLink+'[/code]\n';
    var code='[align=center][size=14][color='+color+'][b]'+fullTitle+'[/b][/color][/size][/align]\n[hr]\n[quote][table layout=fixed width=100%][tr][td]'+lines.join('\n')+'[/td][td][align=center][img]'+(v('image')||'адрес картинки')+'[/img][/align][/td][/tr][/table]\n[hr]\n[table layout=fixed width=100%][tr][td][b]Описание:[/b] [i]'+(v('description')||'...')+'[/i][/td][/tr][/table]\n[hr]\n[table layout=fixed width=100%][tr][td][b][color=red]Примечание:[/color][/b]\n'+notes.map(function(x){return '● [i]'+x+'[/i]';}).join('\n')+'[/td][/tr][/table]\n[b]Пользователи:[/b] [i][color=navy]'+(v('users')||'Фамилия Имя')+'[/color][/i][/quote]\n[hr]\n'+parameterCode+'[color=green][align=right][i]By '+(v('author')||'ник создателя')+'[/i][/align][/color]\n[hr]';app.querySelector('.aab-output').value=code.replace(/\[\/?widepost\]/gi,'');app.querySelector('.aab-parameter-output').value=parameterLink;app.querySelector('.aab-summary').textContent=fullTitle+' · '+v('rank')+(weapon?' · '+damage+' · крит '+critical+' / '+chance+'%':' · Поддержка');
  }
  function updateCatalog(){app.querySelector('datalist').innerHTML=catalog.map(function(w){return '<option value="'+esc(w.name)+'">'+esc(w.group+' · '+w.rank)+'</option>';}).join('');}
  function applyWeapon(){if(v('kind')!=='weapon'){render();return;}var item=catalog.find(function(w){return w.name.toLowerCase()===v('base').toLowerCase();});if(!item){selected=null;render();return;}selected=item;q('damageType').value=item.type;q('damage').value=item.damage;var m=item.critical.match(/\((?:[^)]*?)(\d+(?:[.,]\d+)?)\s*%[^)]*\)/i);q('critical').value=item.critical.replace(/\s*\([^)]*%[^)]*\)/g,'').trim();q('chance').value=m?Number(m[1].replace(',','.')):0;q('requirements').value=item.requirements;q('notes').value=item.bonus&&!/^[-—–]$/.test(item.bonus)?item.bonus:'';['extraDamage','extraCritical','extraChance'].forEach(function(k){q(k).value=0;});render();}
  function parseCatalog(html){var doc=new DOMParser().parseFromString(html,'text/html'),items=[];Array.prototype.forEach.call(doc.querySelectorAll('.spoiler-box'),function(box){var heading=box.firstElementChild;if(!heading)return;var group=heading.textContent.trim();if(group!=='Стандартное вооружение'&&group!=='Дополнительное оружие')return;var table=box.querySelector('table');if(!table)return;var rows=table.rows;if(!rows.length)return;function cells(row){return Array.prototype.map.call(row.cells,function(cell){return cell.textContent.replace(/\s+/g,' ').trim();});}var headers=cells(rows[0]).map(function(x){return x.toLowerCase();});function index(label){return headers.indexOf(label.toLowerCase());}var keys={type:'Тип',rank:'Ранг',name:'Название',damage:'Урон',critical:'Критический урон',bonus:'Бонусы',requirements:'Требования'};if(Object.keys(keys).some(function(k){return index(keys[k])<0;}))return;Array.prototype.forEach.call(rows,function(row,i){if(!i)return;var c=cells(row),item={group:group};Object.keys(keys).forEach(function(k){item[k]=c[index(keys[k])]||'';});if(/^[EDCBAS]$/.test(item.rank)&&item.name)items.push(item);});});return items;}
  var loaded=false;launch.onclick=function(){app.hidden=false;launch.hidden=true;if(!loaded){loaded=true;fetch('/viewtopic.php?id=82',{credentials:'same-origin'}).then(function(r){if(!r.ok)throw new Error();return r.arrayBuffer();}).then(function(buffer){var items=parseCatalog(new TextDecoder('windows-1251').decode(buffer));if(!items.length)throw new Error();catalog=items;updateCatalog();app.querySelector('.aab-status').textContent='Каталог обновлён из темы №82: '+items.length+' видов оружия.';}).catch(function(){app.querySelector('.aab-status').textContent='Используется встроенный каталог. Все поля можно редактировать вручную.';});}app.scrollIntoView({behavior:'smooth',block:'start'});};app.querySelector('.atb-close').onclick=function(){app.hidden=true;launch.hidden=false;};
  app.addEventListener('input',function(e){if(e.target===q('base'))applyWeapon();else render();});app.addEventListener('change',function(e){if(e.target===q('base'))applyWeapon();else render();});
