  app.querySelector('.aab-insert').onclick=function(){var editor=document.querySelector('textarea[name="req_message"],#main-reply,textarea[name="message"]');if(!editor){app.querySelector('.aab-status').textContent='Форма ответа не найдена — скопируйте код.';return;}editor.value=app.querySelector('.aab-output').value.replace(/\[\/?widepost\]/gi,'');editor.dispatchEvent(new Event('input',{bubbles:true}));editor.scrollIntoView({behavior:'smooth',block:'center'});};q('rank').value='D';q('author').value=window.UserLogin||'';updateCatalog();render();
